with q as (select * from (values
('pcac-2026-pccr-lei-2250-2009-lei-3228-2017-lc-496-2025','pcac-law3228-absorbed-benefits-05','Lei nº 3.228/2017 — parcelas absorvidas','Segundo o art. 5º, § 1º, da Lei nº 3.228/2017, quais parcelas foram absorvidas no vencimento básico dos cargos abrangidos pelo plano?','(A) Gratificação natalina, adicional de férias e diárias.\n(B) Adicional de atividade policial, gratificação de risco de vida e etapa alimentação.\n(C) Adicional de titulação, gratificação de chefia e gratificação de instrução.\n(D) VAP, gratificação de chefia e sexta parte.\n(E) Apenas etapa alimentação.','B','O § 1º do art. 5º enumera três parcelas absorvidas no vencimento básico: adicional de atividade policial, gratificação de risco de vida e etapa alimentação. Não devem ser somadas novamente como adicionais autônomos.'),
('pcac-2026-pccr-lei-2250-2009-lei-3228-2017-lc-496-2025','pcac-law3228-vap-exclusion-06','Lei nº 3.228/2017 — exclusão do VAP','Para os cargos contemplados pela Lei nº 3.228/2017, o que estabelece o art. 5º, § 2º, sobre o Prêmio Anual de Valorização da Atividade Policial (VAP)?','(A) É pago obrigatoriamente em dobro.\n(B) É incorporado ao vencimento básico.\n(C) Não se aplica aos cargos contemplados pela Lei nº 3.228/2017.\n(D) Substitui o adicional de titulação.\n(E) É devido apenas na Classe Especial.','C','O § 2º do art. 5º exclui expressamente os cargos abrangidos pela Lei nº 3.228/2017 do VAP previsto no art. 22, IX, da Lei nº 2.250/2009.')
) as t(material_slug,external_item_key,subtopic,question_text,options_text,answer,explanation))
